-- seed graphite: сгенерировано tenant:sql, повторный запуск обновляет настройки
on conflict(slug) do update set timezone=excluded.timezone,buffer_minutes=excluded.buffer_minutes,config=excluded.config;
update categories set description='Свежие салаты для повседневного стола и мероприятий.',image_url='/tenants/graphite/images/work1.svg',active=true,sort_order=0 where tenant_id=(select id from tenants where slug='graphite') and name='🥗 Салаты';
update categories set description='Закуски для фуршета, праздника и встречи гостей.',image_url='/tenants/graphite/images/work2.svg',active=true,sort_order=1 where tenant_id=(select id from tenants where slug='graphite') and name='🍢 Закуски';
update categories set description='Горячие блюда, приготовленные с вниманием к подаче.',image_url='/tenants/graphite/images/work3.svg',active=true,sort_order=2 where tenant_id=(select id from tenants where slug='graphite') and name='🥩 Горячие блюда';
update services set category_id=(select id from categories where tenant_id=(select id from tenants where slug='graphite') and name='🥗 Салаты'),price_cents=320000,duration_minutes=20,active=true,description='Салат с креветками, свежими листьями и фирменной заправкой.',image_url=null where tenant_id=(select id from tenants where slug='graphite') and name='Салат Цезарь с креветками';
update services set category_id=(select id from categories where tenant_id=(select id from tenants where slug='graphite') and name='🥗 Салаты'),price_cents=250000,duration_minutes=15,active=true,description='Овощи, сыр и оливки в средиземноморском стиле.',image_url=null where tenant_id=(select id from tenants where slug='graphite') and name='Салат Греческий';
update services set category_id=(select id from categories where tenant_id=(select id from tenants where slug='graphite') and name='🍢 Закуски'),price_cents=450000,duration_minutes=30,active=true,description='Ассорти закусочных брускетт для фуршета.',image_url=null where tenant_id=(select id from tenants where slug='graphite') and name='Ассорти брускетт';
update services set category_id=(select id from categories where tenant_id=(select id from tenants where slug='graphite') and name='🥩 Горячие блюда'),price_cents=850000,duration_minutes=45,active=true,description='Стейк с подачей от шефа. Степень прожарки уточняется при подтверждении.',image_url=null where tenant_id=(select id from tenants where slug='graphite') and name='Стейк из мраморной говядины';
