insert into tenants(slug,status,timezone,buffer_minutes,config) values('graphite','preview','Asia/Aqtobe',15,'{"slug":"graphite","name":"Chef & Catering Hub","short_name":"ChefHub","accent":"#FF8A24","accent_purple":"#B879EE","timezone":"Asia/Aqtobe","currency":"₸","buffer_minutes":15,"slot_minutes":30,"cancel_hours":12,"demo":true,"phone":"+7 7470356684","address":"Костанай","description":"Выездной повар и доставка изысканной еды на дом и мероприятия","images":{"logo":"images/logo.svg","hero":"images/hero.svg"},"gallery":[{"image":"images/work1.svg","caption":"Банкетные закуски"},{"image":"images/work2.svg","caption":"Горячие блюда от шефа"},{"image":"images/work3.svg","caption":"Десерты и подача"}],"cards":{"booking":{"title":"Заказ еды и выезд повара","text":"Соберите меню, укажите дату, формат и количество гостей"},"ai":{"title":"Помощник по меню","text":"Поможет подобрать блюда под ваше событие"},"install":{"title":"Ресторан у вас дома","text":"Оформляйте доставку или приглашайте шефа в несколько кликов."}},"resources":["Шеф-повар","Су-шеф","Служба доставки"],"hours":{"mon":["10:00","22:00"],"tue":["10:00","22:00"],"wed":["10:00","22:00"],"thu":["10:00","22:00"],"fri":["10:00","23:00"],"sat":["10:00","23:00"],"sun":["10:00","22:00"]},"categories":[{"id":"salads","name":"🥗 Салаты","description":"Свежие салаты для повседневного стола и мероприятий.","active":true,"image":"images/work1.svg"},{"id":"appetizers","name":"🍢 Закуски","description":"Закуски для фуршета, праздника и встречи гостей.","active":true,"image":"images/work2.svg"},{"id":"hot","name":"🥩 Горячие блюда","description":"Горячие блюда, приготовленные с вниманием к подаче.","active":true,"image":"images/work3.svg"}],"services":[{"name":"Салат Цезарь с креветками","price":3200,"duration_minutes":20,"category":"salads","description":"Салат с креветками, свежими листьями и фирменной заправкой."},{"name":"Салат Греческий","price":2500,"duration_minutes":15,"category":"salads","description":"Овощи, сыр и оливки в средиземноморском стиле."},{"name":"Ассорти брускетт","price":4500,"duration_minutes":30,"category":"appetizers","description":"Ассорти закусочных брускетт для фуршета."},{"name":"Стейк из мраморной говядины","price":8500,"duration_minutes":45,"category":"hot","description":"Стейк с подачей от шефа. Степень прожарки уточняется при подтверждении."}]}'::jsonb)
insert into resources(tenant_id,name) select id,'Шеф-повар' from tenants where slug='graphite' and not exists(select 1 from resources x where x.tenant_id=tenants.id and x.name='Шеф-повар');
insert into resources(tenant_id,name) select id,'Су-шеф' from tenants where slug='graphite' and not exists(select 1 from resources x where x.tenant_id=tenants.id and x.name='Су-шеф');
insert into resources(tenant_id,name) select id,'Служба доставки' from tenants where slug='graphite' and not exists(select 1 from resources x where x.tenant_id=tenants.id and x.name='Служба доставки');
insert into categories(tenant_id,name,description,image_url,active,sort_order) select t.id,'🥗 Салаты','Свежие салаты для повседневного стола и мероприятий.','/tenants/graphite/images/work1.svg',true,0 from tenants t where t.slug='graphite' and not exists(select 1 from categories x where x.tenant_id=t.id and x.name='🥗 Салаты');
insert into categories(tenant_id,name,description,image_url,active,sort_order) select t.id,'🍢 Закуски','Закуски для фуршета, праздника и встречи гостей.','/tenants/graphite/images/work2.svg',true,1 from tenants t where t.slug='graphite' and not exists(select 1 from categories x where x.tenant_id=t.id and x.name='🍢 Закуски');
insert into categories(tenant_id,name,description,image_url,active,sort_order) select t.id,'🥩 Горячие блюда','Горячие блюда, приготовленные с вниманием к подаче.','/tenants/graphite/images/work3.svg',true,2 from tenants t where t.slug='graphite' and not exists(select 1 from categories x where x.tenant_id=t.id and x.name='🥩 Горячие блюда');
insert into services(tenant_id,category_id,name,price_cents,duration_minutes,active,description,image_url) select t.id,(select id from categories where tenant_id=(select id from tenants where slug='graphite') and name='🥗 Салаты'),'Салат Цезарь с креветками',320000,20,true,'Салат с креветками, свежими листьями и фирменной заправкой.',null from tenants t where t.slug='graphite' and not exists(select 1 from services x where x.tenant_id=t.id and x.name='Салат Цезарь с креветками');
insert into services(tenant_id,category_id,name,price_cents,duration_minutes,active,description,image_url) select t.id,(select id from categories where tenant_id=(select id from tenants where slug='graphite') and name='🥗 Салаты'),'Салат Греческий',250000,15,true,'Овощи, сыр и оливки в средиземноморском стиле.',null from tenants t where t.slug='graphite' and not exists(select 1 from services x where x.tenant_id=t.id and x.name='Салат Греческий');
